CREATE TABLE admissions (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, class_id text NOT NULL, created_by text NOT NULL, name text NOT NULL, guardian_name text NOT NULL, guardian_email text NOT NULL, notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','changes_requested','approved','rejected')), revision integer NOT NULL DEFAULT 1, student_id text, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), UNIQUE(org_id,student_id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,class_id) REFERENCES classes(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id));
CREATE TABLE review_decisions (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, entity text NOT NULL, entity_id text NOT NULL, revision integer NOT NULL, actor_id text NOT NULL, decision text NOT NULL, comment text NOT NULL CHECK(length(comment)>0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES users(org_id,id));
CREATE INDEX decision_record ON review_decisions(org_id,entity,entity_id,created_at);
CREATE TABLE transfers (id text PRIMARY KEY, org_id text NOT NULL, branch_id text NOT NULL, student_id text NOT NULL, created_by text NOT NULL, destination_class_id text, external_destination text, notes text NOT NULL, status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','approved','rejected','changes_requested')), revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), CHECK((destination_class_id IS NULL)<>(external_destination IS NULL)), UNIQUE(org_id,id), FOREIGN KEY(org_id,branch_id) REFERENCES branches(org_id,id), FOREIGN KEY(org_id,student_id) REFERENCES students(org_id,id), FOREIGN KEY(org_id,created_by) REFERENCES users(org_id,id), FOREIGN KEY(org_id,destination_class_id) REFERENCES classes(org_id,id));
